def compute(vars):
    value_2019 = vars["v1"]
    value_2018 = vars["v2"]

    if value_2019 > value_2018:
        year = 2019
    elif value_2018 > value_2019:
        year = 2018
    else:
        year = None

    return {
        "value": year,
        "trace": {
            "value_2019": value_2019,
            "value_2018": value_2018,
            "comparison": "2019 > 2018" if year == 2019 else ("2018 > 2019" if year == 2018 else "equal"),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
